if PLAN['status'] != 'final':
    try:
        evaluation.validate_plan(PLAN, ROOT)
    except ValueError as error:
        if str(error) != 'Final Classification configuration unresolved':
            raise
        print('VERIFIED expected refusal:', str(error))
    else:
        raise AssertionError('Draft plan unexpectedly accepted')
else:
    print('Final plan present: complete readiness checks require separately approved TASK 6')

